  const der=Buffer.concat([Buffer.from('302a300506032b6570032100','hex'),hex(pub)]);
  return crypto.verify(null,Buffer.from(msg),{key:der,format:'der',type:'spki'},hex(sig));
}
function jcs(v){
  if(v===null) return 'null';
  if(typeof v==='string') return JSON.stringify(v);
